const g = globalThis as unknown as { __teamPortalStore?: Store };

export const db: Store = g.__teamPortalStore ?? (g.__teamPortalStore = seed());

export function delay(min: number, max: number) {
  const ms = Math.round(min + Math.random() * (max - min));
  return new Promise((r) => setTimeout(r, ms));
}

export async function listProjects() {
  await delay(40, 160);
  return db.projects.map((p) => ({ ...p }));
}

export async function getProject(id: string) {
  await delay(40, 160);
  const p = db.projects.find((p) => p.id === id);
  return p ? { ...p } : null;
}

export function writeProject(id: string, patch: Partial<Omit<Project, "id">>) {
  const p = db.projects.find((p) => p.id === id);
  if (!p) return null;
  Object.assign(p, patch, { updatedAt: new Date().toISOString() });
  db.activity.unshift({
    id: `a${Date.now()}`,
    who: `${db.profile.firstName} ${db.profile.lastName}`,
    what: "updated",
    target: p.name,
    at: p.updatedAt,
  });
  db.activity = db.activity.slice(0, 8);
  return { ...p };
}

export async function listPhotos() {
  await delay(30, 120);
  return db.photos.map((p) => ({ ...p }));
}

export async function getPhoto(id: string) {
  await delay(30, 120);
  const p = db.photos.find((p) => p.id === id);
  return p ? { ...p } : null;
}

export async function getProfile() {
  await delay(30, 100);
  return { ...db.profile };
}

export async function getActivity() {
  await delay(900, 1400);
  return db.activity.map((a) => ({ ...a }));
}
